  vec4 ret = vec4(0.0);
  vec2 uv = vUv;
  vec2 uv_orig = vUvOriginal;
  float rad = vRadius;
  float ang = vAngle;
  // sample previous uFrame
    ret.xyz = texture( sampler_main, uv ).xyz;

      // take the difference between the crisp and blurred images,
      // then add it back into the image.  Creates spots and stripes over uTime.
      ret.xyz += (ret.xyz - GetBlur2(uv))*0.3;
      ret.xyz *= 0.9;

      // add noise:
      vec2 dither_uv = uv_orig*uTexSize.xy*texsize_noise_lq.zw * 0.4 + rand_frame.xy;
